}/* ==================================================
   Modernized & Resizable Blogger Share Buttons
   ================================================== */

/* 1. Quick Customization Controls */
:root {
  --share-btn-size: 13px;          /* Resize font size (Controls overall scale) */
  --share-btn-padding: 8px 16px;   /* Vertical and Horizontal inner spacing */
  --share-btn-radius: 20px;        /* 20px for pill style | 6px for soft square */
  --share-btn-bg: #f1f5f9;         /* Neutral button background */
  --share-btn-color: #334155;      /* Text and icon color */
  --share-btn-hover-bg: #2563eb;   /* Default hover background color */
  --share-btn-hover-color: #ffffff;/* Default hover text color */
}

/* 2. Share Buttons Container Alignment */
.post-share-buttons,
.sharing-buttons,
.post-footer-line {
  display: flex !important;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: 12px 0;
}

/* 3. Base Button Styling (Overrides Blogger Default Styles) */
a.goog-inline-block[class*="sharing-"],
.sharing-platform-button {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px;
  padding: var(--share-btn-padding) !important;
  font-size: var(--share-btn-size) !important;
  font-weight: 600 !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important;
  color: var(--share-btn-color) !important;
  background-color: var(--share-btn-bg) !important;
  border-radius: var(--share-btn-radius) !important;
  border: 1px solid rgba(0, 0, 0, 0.06) !important;
  text-decoration: none !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
  cursor: pointer;
  transition: all 0.2s ease-in-out !important;
  line-height: 1 !important;
}

/* Hover & Active Effects */
a.goog-inline-block[class*="sharing-"]:hover,
.sharing-platform-button:hover {
  background-color: var(--share-btn-hover-bg) !important;
  color: var(--share-btn-hover-color) !important;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.2);
  border-color: transparent !important;
}

/* Active Click Effect */
a.goog-inline-block[class*="sharing-"]:active,
.sharing-platform-button:active {
  transform: translateY(0);
}

/* 4. Text & SVG Icon Cleanups */
.share-button-link-text,
.platform-sharing-text {
  display: inline-block;
  vertical-align: middle;
}

/* Auto-scale SVG icons inside buttons if present */
a.goog-inline-block[class*="sharing-"] svg,
.sharing-platform-button svg {
  width: 1.15em !important;
  height: 1.15em !important;
  fill: currentColor !important;
}

/* ==================================================
   Optional: Individual Brand Hover Colors
   ================================================== */
a.sharing-facebook:hover {
  background-color: #1877f2 !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(24, 119, 242, 0.3) !important;
}

a.sharing-twitter:hover,
a.sharing-x:hover {
  background-color: #0f1419 !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(15, 20, 25, 0.3) !important;
}

a.sharing-pinterest:hover {
  background-color: #e60023 !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(230, 0, 35, 0.3) !important;
}

.sharing-element-other:hover {
  background-color: #475569 !important;
  color: #ffffff !important;
  box-shadow: 0 4px 12px rgba(71, 85, 105, 0.3) !important;
}
/* Completely hide the main oversized share toggle box */
.sharing-button,
.post-share-buttons-byline,
.sharing-button-container {
  display: none !important;
}
/* --- SHARE BUTTONS - FIX SIZES --- */
.news-card-share {
  display: flex !important;
  align-items: center !important;
  gap: 4px !important;
  flex-wrap: wrap !important;
}

.share-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 32px !important;
  height: 32px !important;
  min-width: 32px !important;
  min-height: 32px !important;
  padding: 0 !important;
  margin: 0 !important;
  border-radius: 4px !important;
  border: none !important;
  text-decoration: none !important;
  color: #fff !important;
  transition: all 0.2s ease !important;
  cursor: pointer !important;
  background: #f0f0f0 !important;
}

/* SVG icons */
.share-btn svg {
  width: 16px !important;
  height: 16px !important;
  fill: #fff !important;
  display: block !important;
}

/* Hide text labels */
.share-btn span {
  display: none !important;
}

/* Platform colors */
.share-btn.facebook { background: #1877f2 !important; }
.share-btn.twitter { background: #000000 !important; }
.share-btn.whatsapp { background: #25d366 !important; }
.share-btn.copylink { background: #6c757d !important; }

.share-btn:hover {
  transform: scale(1.1) !important;
  opacity: 0.85 !important;
  text-decoration: none !important;
}

/* --- FIX CARD FOOTER LAYOUT --- */
.news-card-footer {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  flex-wrap: wrap !important;
  gap: 8px !important;
  margin-top: 10px !important;
  padding-top: 10px !important;
  border-top: 1px solid #e5e5e5 !important;
}

.news-card-date {
  font-size: 12px !important;
  color: #888 !important;
}

/* Mobile responsive */
@media screen and (max-width: 768px) {
  .share-btn {
    width: 28px !important;
    height: 28px !important;
    min-width: 28px !important;
    min-height: 28px !important;
  }

  .share-btn svg {
    width: 14px !important;
    height: 14px !important;
  }
}

/* Responsive Sidebar */
@media screen and (max-width: 1024px) {
  body.item-view .sidebar-wrapper,
  body.static_page .sidebar-wrapper {
    display: block;
    margin-top: 30px;
  }

  body.item-view .content-wrapper,
  body.static_page .content-wrapper {
    grid-template-columns: 1fr !important;
  }

  .sidebar-wrapper {
    grid-column: 1 / -1 !important;
  }
}
    }
}

head.b:template-skin:

  body#layout .hidden,
  body#layout .invisible {
    display: inherit;
  }
  body#layout .navigation {
    display: none;
  }

  body#layout .page {
    float: right;
    margin-left: 20px;
    width: 55%;
  }
  body#layout .hamburger-menu {
    display: none;
  }

  /* ============================================
     CLEAN DESKTOP LAYOUT - BBC STYLE
     ============================================ */

  /* --- HOMEPAGE: Full Width, No Sidebar --- */
  .homepage .content-wrapper {
    display: block !important;
    max-width: 1600px !important;
    margin: 0 auto !important;
    padding: 0 40px !important;
  }

  .homepage #main {
    max-width: 100% !important;
    width: 100% !important;
  }

  .homepage .sidebar-wrapper {
    display: none !important;
  }

  /* --- POST PAGES: Full Width Content with Sidebar --- */
  .item-view .content-wrapper,
  .static_page .content-wrapper {
    display: grid !important;
    grid-template-columns: 1fr 280px !important;
    gap: 40px !important;
    max-width: 1600px !important;
    margin: 0 auto !important;
    padding: 20px 40px !important;
  }

  .item-view #main,
  .static_page #main {
    grid-column: 1 / 2 !important;
    max-width: 100% !important;
    min-width: 0 !important;
  }

  .item-view .sidebar-wrapper,
  .static_page .sidebar-wrapper {
    grid-column: 2 / 3 !important;
    display: block !important;
    position: sticky !important;
    top: 20px !important;
    height: fit-content !important;
  }

  /* --- SIDEBAR STYLES --- */
  .sidebar-wrapper {
    margin-top: 0 !important;
  }

  .sidebar-container {
    background: #ffffff !important;
    border-radius: 8px !important;
    padding: 20px !important;
    border: 1px solid #f0f2f5 !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06) !important;
  }

  /* Compact sidebar widget styling */
  .sidebar-wrapper .widget {
    margin-bottom: 25px !important;
    padding-bottom: 25px !important;
    border-bottom: 1px solid #eaeaea !important;
    background: #fff !important;
    padding: 20px !important;
    border-radius: 8px !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06) !important;
    transition: all 0.3s ease !important;
  }

  .sidebar-wrapper .widget:hover {
    box-shadow: 0 4px 15px rgba(0,0,0,0.1) !important;
    transform: translateY(-2px) !important;
  }

  .sidebar-wrapper .widget:last-child {
    border-bottom: none !important;
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
  }

  .sidebar-wrapper .widget h2,
  .sidebar-wrapper .widget h3 {
    font-size: 14px !important;
    font-weight: 700 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
    color: #1a1a1a !important;
    margin-bottom: 15px !important;
    padding-bottom: 10px !important;
    border-bottom: 2px solid #e31837 !important;
    position: relative !important;
  }

  /* Animated underline on sidebar titles */
  .sidebar-wrapper .widget h2::after,
  .sidebar-wrapper .widget h3::after {
    content: '' !important;
    position: absolute !important;
    bottom: -2px !important;
    left: 0 !important;
    width: 50px !important;
    height: 2px !important;
    background: linear-gradient(90deg, #e31837, #ff6b81) !important;
    transition: width 0.3s ease !important;
  }

  .sidebar-wrapper .widget:hover h2::after,
  .sidebar-wrapper .widget:hover h3::after {
    width: 100% !important;
  }

  .sidebar-wrapper .widget ul {
    list-style: none !important;
    padding: 0 !important;
    margin: 0 !important;
  }

  .sidebar-wrapper .widget ul li {
    margin-bottom: 10px !important;
    padding: 8px 0 !important;
    border-bottom: 1px solid #f5f5f5 !important;
    transition: all 0.2s ease !important;
  }

  .sidebar-wrapper .widget ul li:last-child {
    border-bottom: none !important;
  }

  .sidebar-wrapper .widget ul li:hover {
    padding-left: 8px !important;
    background: linear-gradient(90deg, rgba(227, 24, 55, 0.05), transparent) !important;
  }

  .sidebar-wrapper .widget ul li a {
    font-size: 14px !important;
    line-height: 1.4 !important;
    color: #333 !important;
    text-decoration: none !important;
    display: block !important;
    padding: 0 !important;
    transition: all 0.2s ease !important;
    position: relative !important;
    padding-left: 12px !important;
  }

  /* Bullet point for sidebar links */
  .sidebar-wrapper .widget ul li a::before {
    content: '•' !important;
    position: absolute !important;
    left: 0 !important;
    color: #e31837 !important;
    font-size: 16px !important;
    line-height: 1 !important;
    transition: transform 0.2s ease !important;
  }

  .sidebar-wrapper .widget ul li:hover a::before {
    transform: translateX(3px) !important;
    color: #ff6b81 !important;
  }

  .sidebar-wrapper .widget ul li a:hover {
    color: #e31837 !important;
    text-decoration: none !important;
  }

  /* --- HOMEPAGE POST GRID (2 Columns) --- */
  .homepage #page_body .widget.Blog .blog-posts {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 25px !important;
  }

  /* --- POST BODY FULL WIDTH ON POST PAGES --- */
  .item-view .post-outer-container,
  .static_page .post-outer-container {
    max-width: 100% !important;
    width: 100% !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
  }

  .item-view .post-body,
  .static_page .post-body {
    font-size: 18px !important;
    line-height: 1.8 !important;
    color: #1a1a1a !important;
    max-width: 100% !important;
  }

  .item-view .post-title,
  .static_page .post-title {
    font-size: 36px !important;
    font-weight: 700 !important;
    line-height: 1.2 !important;
  }

  /* --- MOBILE RESPONSIVE --- */
  @media screen and (max-width: 1024px) {
    .homepage .content-wrapper,
    .item-view .content-wrapper,
    .static_page .content-wrapper {
      display: block !important;
      padding: 0 15px !important;
    }

    .homepage #main,
    .item-view #main,
    .static_page #main {
      max-width: 100% !important;
      width: 100% !important;
    }

    .homepage .sidebar-wrapper,
    .item-view .sidebar-wrapper,
    .static_page .sidebar-wrapper {
      display: block !important;
      margin-top: 20px !important;
      width: 100% !important;
    }
  }

  @media screen and (max-width: 768px) {
    .homepage #page_body .widget.Blog .blog-posts {
      grid-template-columns: 1fr !important;
      gap: 20px !important;
    }

    .item-view .post-title,
    .static_page .post-title {
      font-size: 28px !important;
    }

    .item-view .post-body,
    .static_page .post-body {
      font-size: 16px !important;
      line-height: 1.7 !important;
    }
  }

  @media screen and (max-width: 480px) {
    .item-view .post-title,
    .static_page .post-title {
      font-size: 24px !important;
    }

    .item-view .post-body,
    .static_page .post-body {
      font-size: 15px !important;
    }
  }
/* ============================================
   FIX FOOTER AND BODY WIDTH
   ============================================ */

/* --- Ensure Body and Page take full width --- */
html, body {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  overflow-x: hidden !important;
}

.page_body {
  max-width: 1600px !important;
  margin: 30px auto !important;
  padding: 0 40px !important;
  width: 100% !important;
  box-sizing: border-box !important;
}

.content-wrapper {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
}

/* --- Fix Footer Full Width --- */
.footer {
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 60px 0 30px !important;
  box-sizing: border-box !important;
}

.footer-container {
  max-width: 1600px !important;
  margin: 0 auto !important;
  padding: 0 40px !important;
  width: 100% !important;
  box-sizing: border-box !important;
  display: grid !important;
  grid-template-columns: repeat(3, 1fr) !important;
  gap: 40px !important;
}

.footer-bottom {
  max-width: 1600px !important;
  margin: 30px auto 0 !important;
  padding: 20px 40px 0 !important;
  width: 100% !important;
  box-sizing: border-box !important;
}

/* --- Fix Attribution --- */
.Attribution {
  width: 100% !important;
  max-width: 100% !important;
  padding: 20px !important;
  box-sizing: border-box !important;
}

/* --- Fix Sidebar Widgets --- */
.sidebar-widget {
  background: #ffffff !important;
  border-radius: 8px !important;
  padding: 20px !important;
  margin-bottom: 25px !important;
  border: 1px solid #f0f2f5 !important;
  box-sizing: border-box !important;
  width: 100% !important;
}

/* --- Fix Post Containers --- */
.post-outer-container,
.news-card {
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
}

.post-outer,
.news-card-content {
  padding: 20px 22px 22px !important;
  box-sizing: border-box !important;
  width: 100% !important;
}

/* --- Responsive Footer Fix --- */
@media screen and (max-width: 768px) {
  .footer-container {
    grid-template-columns: 1fr !important;
    gap: 30px !important;
    text-align: center !important;
  }

  .footer-widget h3::after {
    left: 50% !important;
    transform: translateX(-50%) !important;
  }

  .footer-bottom {
    flex-direction: column !important;
    text-align: center !important;
  }
}

div.script:
//
document.addEventListener('DOMContentLoaded', function() {
  // Mobile menu toggle functionality
  var mobileToggleBtn = document.getElementById('mobileMenuToggle');
  var mobileNavContainer = document.getElementById('mobileNavContainer');

  if (mobileToggleBtn && mobileNavContainer) {
    mobileToggleBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      this.classList.toggle('active');
      mobileNavContainer.classList.toggle('active');
    });

    // Close mobile menu when clicking outside
    document.addEventListener('click', function(e) {
      if (!mobileNavContainer.contains(e.target) && !mobileToggleBtn.contains(e.target)) {
        mobileToggleBtn.classList.remove('active');
        mobileNavContainer.classList.remove('active');
      }
    });
  }

  /* ============================================
     COOL FEATURES - SCROLL PROGRESS & BACK TO TOP
     ============================================ */

  // Create scroll progress bar
  var progressBar = document.createElement('div');
  progressBar.className = 'scroll-progress';
  document.body.insertBefore(progressBar, document.body.firstChild);

  // Create scroll to top button
  var scrollToTopBtn = document.createElement('div');
  scrollToTopBtn.className = 'scroll-to-top';
  scrollToTopBtn.innerHTML = '<svg viewBox="0 0 24 24"><path d="M12 4l-8 8h6v8h4v-8h6z"/></svg>';
  document.body.appendChild(scrollToTopBtn);

  // Scroll event handler
  window.addEventListener('scroll', function() {
    // Update scroll progress bar
    var winScroll = document.body.scrollTop || document.documentElement.scrollTop;
    var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
    var scrolled = (winScroll / height) * 100;
    progressBar.style.width = scrolled + '%';

    // Show/hide scroll to top button
    if (winScroll > 300) {
      scrollToTopBtn.classList.add('visible');
    } else {
      scrollToTopBtn.classList.remove('visible');
    }
  });

  // Scroll to top functionality
  scrollToTopBtn.addEventListener('click', function() {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  });

  // Add page load animation
  document.body.classList.add('page-load-animation');
});
//
